49: static inline void emit(struct internal_state *state,
50:                         uint32_t data, int bits)
51: {
52:     /**
53:        Emit sequence of bits.
54:      */
55: 
56:     if (bits <= state->bits) {
57:         state->bits -= bits;
58:         *state->cds += (uint8_t)(data << state->bits);
59:     } else {
60:         bits -= state->bits;
61:         *state->cds++ += (uint8_t)((uint64_t)data >> bits);
62: 
63:         while (bits > 8) {
64:             bits -= 8;
65:             *state->cds++ = (uint8_t)(data >> bits);
66:         }
67: 
68:         state->bits = 8 - bits;
69:         *state->cds = (uint8_t)(data << state->bits);
70:     }
71: }
72: 
73: static inline void emitfs(struct internal_state *state, int fs)
74: {
75:     /**
76:        Emits a fundamental sequence.
77: 
78:        fs zero bits followed by one 1 bit.
79:      */
80: 
81:     for(;;) {
82:         if (fs < state->bits) {
83:             state->bits -= fs + 1;
84:             *state->cds += 1U << state->bits;
85:             break;
86:         } else {
87:             fs -= state->bits;
88:             *++state->cds = 0;
89:             state->bits = 8;
90:         }
91:     }
92: }
93: 
94: static inline void copy64(uint8_t *dst, uint64_t src)
95: {
96:     dst[0] = (uint8_t)(src >> 56);
97:     dst[1] = (uint8_t)(src >> 48);
98:     dst[2] = (uint8_t)(src >> 40);
99:     dst[3] = (uint8_t)(src >> 32);
100:     dst[4] = (uint8_t)(src >> 24);
101:     dst[5] = (uint8_t)(src >> 16);
102:     dst[6] = (uint8_t)(src >> 8);
103:     dst[7] = (uint8_t)src;
104: }
105: 
106: static inline void emitblock_fs(struct aec_stream *strm, int k, int ref)
107: {
108:     struct internal_state *state = strm->state;
109: 
110:     uint64_t acc = (uint64_t)*state->cds << 56;
111:     uint32_t used = 7 - state->bits; /* used bits in 64 bit accumulator */
112: 
113:     for (size_t i = ref; i < strm->block_size; i++) {
114:         used += (state->block[i] >> k) + 1;
115:         while (used > 63) {
116:             copy64(state->cds, acc);
117:             state->cds += 8;
118:             acc = 0;
119:             used -= 64;
120:         }
121:         acc |= UINT64_C(1) << (63 - used);
122:     }
123: 
124:     copy64(state->cds, acc);
125:     state->cds += used >> 3;
126:     state->bits = 7 - (used & 7);
127: }
