129: static inline void emitblock(struct aec_stream *strm, int k, int ref)
130: {
131:     /**
132:        Emit the k LSB of a whole block of input data.
133:     */
134: 
135:     struct internal_state *state = strm->state;
136:     uint32_t *in = state->block + ref;
137:     uint32_t *in_end = state->block + strm->block_size;
138:     uint64_t mask = (UINT64_C(1) << k) - 1;
139:     uint8_t *o = state->cds;
140:     uint64_t a = *o;
141:     int p = state->bits;
142: 
143:     while(in < in_end) {
144:         a <<= 56;
145:         p = (p % 8) + 56;
146: 
147:         while (p > k && in < in_end) {
148:             p -= k;
149:             a += ((uint64_t)(*in++) & mask) << p;
150:         }
151: 
152:         switch (p & ~7) {
153:         case 0:
154:             o[0] = (uint8_t)(a >> 56);
155:             o[1] = (uint8_t)(a >> 48);
156:             o[2] = (uint8_t)(a >> 40);
157:             o[3] = (uint8_t)(a >> 32);
158:             o[4] = (uint8_t)(a >> 24);
159:             o[5] = (uint8_t)(a >> 16);
160:             o[6] = (uint8_t)(a >> 8);
161:             o += 7;
162:             break;
163:         case 8:
164:             o[0] = (uint8_t)(a >> 56);
165:             o[1] = (uint8_t)(a >> 48);
166:             o[2] = (uint8_t)(a >> 40);
167:             o[3] = (uint8_t)(a >> 32);
168:             o[4] = (uint8_t)(a >> 24);
169:             o[5] = (uint8_t)(a >> 16);
170:             a >>= 8;
171:             o += 6;
172:             break;
173:         case 16:
174:             o[0] = (uint8_t)(a >> 56);
175:             o[1] = (uint8_t)(a >> 48);
176:             o[2] = (uint8_t)(a >> 40);
177:             o[3] = (uint8_t)(a >> 32);
178:             o[4] = (uint8_t)(a >> 24);
179:             a >>= 16;
180:             o += 5;
181:             break;
182:         case 24:
183:             o[0] = (uint8_t)(a >> 56);
184:             o[1] = (uint8_t)(a >> 48);
185:             o[2] = (uint8_t)(a >> 40);
186:             o[3] = (uint8_t)(a >> 32);
187:             a >>= 24;
188:             o += 4;
189:             break;
190:         case 32:
191:             o[0] = (uint8_t)(a >> 56);
192:             o[1] = (uint8_t)(a >> 48);
193:             o[2] = (uint8_t)(a >> 40);
194:             a >>= 32;
195:             o += 3;
196:             break;
197:         case 40:
198:             o[0] = (uint8_t)(a >> 56);
199:             o[1] = (uint8_t)(a >> 48);
200:             a >>= 40;
201:             o += 2;
202:             break;
203:         case 48:
204:             *o++ = (uint8_t)(a >> 56);
205:             a >>= 48;
206:             break;
207:         default:
208:             a >>= 56;
209:             break;
210:         }
211:     }
212: 
213:     *o = (uint8_t)a;
214:     state->cds = o;
215:     state->bits = p % 8;
216: }
