218: static void preprocess_unsigned(struct aec_stream *strm)
219: {
220:     /**
221:        Preprocess RSI of unsigned samples.
222: 
223:        Combining preprocessing and converting to uint32_t in one loop
224:        is slower due to the data dependence on x_i-1.
225:     */
226: 
227:     uint32_t D;
228:     struct internal_state *state = strm->state;
229:     const uint32_t *x = state->data_raw;
230:     uint32_t *d = state->data_pp;
231:     uint32_t xmax = state->xmax;
232:     uint32_t rsi = strm->rsi * strm->block_size - 1;
233: 
234:     state->ref = 1;
235:     state->ref_sample = x[0];
236:     d[0] = 0;
237:     for (size_t i = 0; i < rsi; i++) {
238:         if (x[i + 1] >= x[i]) {
239:             D = x[i + 1] - x[i];
240:             if (D <= x[i])
241:                 d[i + 1] = 2 * D;
242:             else
243:                 d[i + 1] = x[i + 1];
244:         } else {
245:             D = x[i] - x[i + 1];
246:             if (D <= xmax - x[i])
247:                 d[i + 1] = 2 * D - 1;
248:             else
249:                 d[i + 1] = xmax - x[i + 1];
250:         }
251:     }
252:     state->uncomp_len = (strm->block_size - 1) * strm->bits_per_sample;
253: }
