255: static void preprocess_signed(struct aec_stream *strm)
256: {
257:     /**
258:        Preprocess RSI of signed samples.
259:     */
260: 
261:     uint32_t D;
262:     struct internal_state *state = strm->state;
263:     uint32_t *x = state->data_raw;
264:     uint32_t *d = state->data_pp;
265:     uint32_t xmax = state->xmax;
266:     uint32_t xmin = state->xmin;
267:     uint32_t rsi = strm->rsi * strm->block_size - 1;
268:     uint32_t m = UINT32_C(1) << (strm->bits_per_sample - 1);
269: 
270:     state->ref = 1;
271:     state->ref_sample = x[0];
272:     d[0] = 0;
273:     /* Sign extension */
274:     x[0] = (x[0] ^ m) - m;
275: 
276:     for (size_t i = 0; i < rsi; i++) {
277:         x[i + 1] = (x[i + 1] ^ m) - m;
278:         if ((int32_t)x[i + 1] < (int32_t)x[i]) {
279:             D = x[i] - x[i + 1];
280:             if (D <= xmax - x[i])
281:                 d[i + 1] = 2 * D - 1;
282:             else
283:                 d[i + 1] = xmax - x[i + 1];
284:         } else {
285:             D = x[i + 1] - x[i];
286:             if (D <= x[i] - xmin)
287:                 d[i + 1] = 2 * D;
288:             else
289:                 d[i + 1] = x[i + 1] - xmin;
290:         }
291:     }
292:     state->uncomp_len = (strm->block_size - 1) * strm->bits_per_sample;
293: }
