910: int aec_encode(struct aec_stream *strm, int flush)
911: {
912:     /**
913:        Finite-state machine implementation of the adaptive entropy
914:        encoder.
915:     */
916:     struct internal_state *state = strm->state;
917: 
918:     state->flush = flush;
919:     strm->total_in += strm->avail_in;
920:     strm->total_out += strm->avail_out;
921: 
922:     while (state->mode(strm) == M_CONTINUE);
923: 
924:     if (state->direct_out) {
925:         int n = (int)(state->cds - strm->next_out);
926:         strm->next_out += n;
927:         strm->avail_out -= n;
928: 
929:         *state->cds_buf = *state->cds;
930:         state->cds = state->cds_buf;
931:         state->direct_out = 0;
932:     }
933:     strm->total_in -= strm->avail_in;
934:     strm->total_out -= strm->avail_out;
935:     return AEC_OK;
936: }
937: 
938: int aec_encode_end(struct aec_stream *strm)
939: {
940:     struct internal_state *state = strm->state;
941: 
942:     int status = AEC_OK;
943:     if (state->flush == AEC_FLUSH && state->flushed == 0)
944:         status = AEC_STREAM_ERROR;
945:     if (state->offsets != NULL) {
946:         vector_destroy(state->offsets);
947:         state->offsets = NULL;
948:     }
949:     cleanup(strm);
950:     return status;
951: }
952: 
953: int aec_encode_count_offsets(struct aec_stream *strm, size_t *count)
954: {
955:     struct internal_state *state = strm->state;
956:     if (state->offsets == NULL) {
957:         *count = 0;
958:         return AEC_RSI_OFFSETS_ERROR;
959:     } else {
960:         *count = vector_size(state->offsets);
961:     }
962:     return AEC_OK;
963: }
964: 
965: int aec_encode_get_offsets(struct aec_stream *strm, size_t *offsets, size_t offsets_count)
966: {
967:     struct internal_state *state = strm->state;
968:     if (state->offsets == NULL) {
969:         return AEC_RSI_OFFSETS_ERROR;
970:     }
971:     if (offsets_count < vector_size(state->offsets)) {
972:         return AEC_MEM_ERROR;
973:     }
974:     memcpy(offsets, vector_data(state->offsets),
975:            vector_size(state->offsets) * sizeof(size_t));
976:     return AEC_OK;
977: }
978: 
979: int aec_encode_enable_offsets(struct aec_stream *strm)
980: {
981:     struct internal_state *state = strm->state;
982: 
983:     if (state->offsets != NULL)
984:         return AEC_RSI_OFFSETS_ERROR;
985: 
986:     state->offsets = vector_create();
987:     vector_push_back(state->offsets, 0);
988:     return AEC_OK;
989: }
990: 
991: int aec_buffer_encode(struct aec_stream *strm)
992: {
993:     int status = aec_encode_init(strm);
994:     if (status != AEC_OK)
995:         return status;
996:     status = aec_encode(strm, AEC_FLUSH);
997:     if (status != AEC_OK) {
998:         cleanup(strm);
999:         return status;
1000:     }
1001:     return aec_encode_end(strm);
1002: }

