52: #define BUFFERSPACE(strm) (strm->avail_in >= strm->state->in_blklen      \
53:                            && strm->avail_out >= strm->state->out_blklen)
54: 
55: #define FLUSH(KIND)                                                      \
56:     static void flush_##KIND(struct aec_stream *strm)                    \
57:     {                                                                    \
58:         uint32_t *flush_end, *bp, half_d;                                \
59:         uint32_t xmax, d, data, m;                                       \
60:         struct internal_state *state = strm->state;                      \
61:                                                                          \
62:         flush_end = state->rsip;                                         \
63:         if (state->pp) {                                                 \
64:             if (state->flush_start == state->rsi_buffer                  \
65:                 && state->rsip > state->rsi_buffer) {                    \
66:                 state->last_out = *state->rsi_buffer;                    \
67:                                                                          \
68:                 if (strm->flags & AEC_DATA_SIGNED) {                     \
69:                     m = UINT32_C(1) << (strm->bits_per_sample - 1);      \
70:                     /* Reference samples have to be sign extended */     \
71:                     state->last_out = (state->last_out ^ m) - m;         \
72:                 }                                                        \
73:                 put_##KIND(strm, (uint32_t)state->last_out);             \
74:                 state->flush_start++;                                    \
75:             }                                                            \
76:                                                                          \
77:             data = state->last_out;                                      \
78:             xmax = state->xmax;                                          \
79:                                                                          \
80:             if (state->xmin == 0) {                                      \
81:                 uint32_t med;                                            \
82:                 med = state->xmax / 2 + 1;                               \
83:                                                                          \
84:                 for (bp = state->flush_start; bp < flush_end; bp++) {    \
85:                     uint32_t mask;                                       \
86:                     d = *bp;                                             \
87:                     half_d = (d >> 1) + (d & 1);                         \
88:                     /*in this case: data >= med == data & med */         \
89:                     mask = (data & med)?xmax:0;                          \
90:                                                                          \
91:                     /*in this case: xmax - data == xmax ^ data */        \
92:                     if (half_d <= (mask ^ data)) {                       \
93:                         data += (d >> 1)^(~((d & 1) - 1));               \
94:                     } else {                                             \
95:                         data = mask ^ d;                                 \
96:                     }                                                    \
97:                     put_##KIND(strm, data);                              \
98:                 }                                                        \
99:                 state->last_out = data;                                  \
100:             } else {                                                     \
101:                 for (bp = state->flush_start; bp < flush_end; bp++) {    \
102:                     d = *bp;                                             \
103:                     half_d = (d >> 1) + (d & 1);                         \
104:                                                                          \
105:                     if ((int32_t)data < 0) {                             \
106:                         if (half_d <= xmax + data + 1) {                 \
107:                             data += (d >> 1)^(~((d & 1) - 1));           \
108:                         } else {                                         \
109:                             data = d - xmax - 1;                         \
110:                         }                                                \
111:                     } else {                                             \
112:                         if (half_d <= xmax - data) {                     \
113:                             data += (d >> 1)^(~((d & 1) - 1));           \
114:                         } else {                                         \
115:                             data = xmax - d;                             \
116:                         }                                                \
117:                     }                                                    \
118:                     put_##KIND(strm, data);                              \
119:                 }                                                        \
120:                 state->last_out = data;                                  \
121:             }                                                            \
122:         } else {                                                         \
123:             for (bp = state->flush_start; bp < flush_end; bp++)          \
124:                 put_##KIND(strm, *bp);                                   \
125:         }                                                                \
126:         state->flush_start = state->rsip;                                \
127:     }
