384: static inline int m_id(struct aec_stream *strm)
385: {
386:     struct internal_state *state = strm->state;
387:     if (strm->avail_in >= strm->state->in_blklen) {
388:         state->id = direct_get(strm, state->id_len);
389:     } else {
390:         if (bits_ask(strm, state->id_len) == 0) {
391:             state->mode = m_id;
392:             return M_EXIT;
393:         }
394:         state->id = bits_get(strm, state->id_len);
395:         bits_drop(strm, state->id_len);
396:     }
397:     state->mode = state->id_table[state->id];
398:     return(state->mode(strm));
399: }
