645: static int m_uncomp_copy(struct aec_stream *strm)
646: {
647:     struct internal_state *state = strm->state;
648: 
649:     do {
650:         if (copysample(strm) == 0)
651:             return M_EXIT;
652:     } while(--state->sample_counter);
653: 
654:     state->mode = m_next_cds;
655:     return M_CONTINUE;
656: }
