809: int aec_decode(struct aec_stream *strm, int flush)
810: {
811:     /**
812:        Finite-state machine implementation of the adaptive entropy
813:        decoder.
814: 
815:        Can work with one byte input und one sample output buffers. If
816:        enough buffer space is available, then faster implementations
817:        of the states are called. Inspired by zlib.
818:     */
819: 
820:     struct internal_state *state = strm->state;
821:     int status;
822: 
823:     strm->total_in += strm->avail_in;
824:     strm->total_out += strm->avail_out;
825: 
826:     do {
827:         status = state->mode(strm);
828:     } while (status == M_CONTINUE);
829: 
830:     if (status == M_ERROR)
831:         return AEC_DATA_ERROR;
832: 
833:     if (status == M_EXIT && strm->avail_out > 0 &&
834:         strm->avail_out < state->bytes_per_sample) {
835:         /* Flush the samples already decoded into rsi_buffer so that
836:          * next_out and avail_out remain consistent with each other.
837:          * The caller can detect partial output via AEC_MEM_ERROR. */
838:         state->flush_output(strm);
839:         strm->total_in -= strm->avail_in;
840:         strm->total_out -= strm->avail_out;
841:         return AEC_MEM_ERROR;
842:     }
843: 
844:     state->flush_output(strm);
845: 
846:     strm->total_in -= strm->avail_in;
847:     strm->total_out -= strm->avail_out;
848: 
849:     return AEC_OK;
850: }
851: 
852: int aec_decode_end(struct aec_stream *strm)
853: {
854:     struct internal_state *state = strm->state;
855:     if (state->offsets != NULL)
856:         vector_destroy(state->offsets);
857: 
858:     free(state->id_table);
859:     free(state->rsi_buffer);
860:     free(state);
861: 
862:     return AEC_OK;
863: }
