901: int aec_decode_range(struct aec_stream *strm, const size_t *rsi_offsets, size_t rsi_offsets_count, size_t pos, size_t size)
902: {
903:     struct internal_state *state = strm->state;
904:     int status;
905:     size_t rsi_size;
906:     size_t rsi_n;
907:     unsigned char *out_tmp;
908:     struct aec_stream strm_tmp = *strm;
909: 
910:     if (strm->avail_out < size)
911:         return AEC_MEM_ERROR;
912: 
913:     if (state->pp) {
914:         state->ref = 1;
915:         state->encoded_block_size = strm->block_size - 1;
916:     } else {
917:         state->ref = 0;
918:         state->encoded_block_size = strm->block_size;
919:     }
920: 
921:     state->rsip = state->rsi_buffer;
922:     state->flush_start = state->rsi_buffer;
923:     state->bitp = 0;
924:     state->fs = 0;
925:     state->mode = m_id;
926: 
927:     rsi_size = strm->rsi * strm->block_size * state->bytes_per_sample;
928:     if (size > SIZE_MAX - (pos % rsi_size) - state->bytes_per_sample - 1)
929:         return AEC_DATA_ERROR;
930:     rsi_n = pos / rsi_size;
931:     if (rsi_n >= rsi_offsets_count)
932:         return AEC_DATA_ERROR;
933: 
934:     /* resize and align to bytes_per_sample */
935:     strm_tmp.total_out = 0;
936:     strm_tmp.avail_out = size + pos % rsi_size + 1;
937:     strm_tmp.avail_out += state->bytes_per_sample - strm_tmp.avail_out % state->bytes_per_sample;
938:     if ((out_tmp = malloc(strm_tmp.avail_out)) == NULL)
939:         return AEC_MEM_ERROR;
940:     strm_tmp.next_out = out_tmp;
941: 
942:     if ((status = aec_buffer_seek(&strm_tmp, rsi_offsets[rsi_n])) != AEC_OK) {
943:         free(out_tmp);
944:         return status;
945:     }
946: 
947:     if ((status = aec_decode(&strm_tmp, AEC_FLUSH)) != 0) {
948:         free(out_tmp);
949:         return status;
950:     }
951: 
952:     memcpy(strm->next_out, out_tmp + (pos - rsi_n * rsi_size), size);
953: 
954:     strm->next_out += size;
955:     strm->avail_out -= size;
956:     strm->total_out += size;
957:     free(out_tmp);
958: 
959:     return AEC_OK;
960: }
